#!/usr/bin/env node
import fs from "node:fs";
import path from "node:path";
import { execFileSync } from "node:child_process";

const root = process.cwd();
const checkOnly = process.argv.includes("--check");
const MARKER = "TIBIAGAME_V36_95_AUTHORITATIVE_APPEARANCE";
const REQUIRED = "TIBIAGAME_V36_94_1_CHARACTER_CUSTOMIZATION_RECOVERY";

const typesPath = path.join(root, "crates/game-types/src/lib.rs");
const protocolPath = path.join(root, "crates/game-protocol/src/lib.rs");
const persistencePath = path.join(root, "crates/game-server/src/persistence.rs");
const worldPath = path.join(root, "crates/game-server/src/world.rs");
const serverMainPath = path.join(root, "crates/game-server/src/main.rs");
const statePath = path.join(root, "crates/game-client/src/state.rs");
const playerPath = path.join(root, "crates/game-client/src/player_sprites.rs");
const clientMainPath = path.join(root, "crates/game-client/src/main.rs");
const remotePath = path.join(root, "crates/game-client/src/remote_player_sprites.rs");
const appearanceUiPath = path.join(root, "crates/game-client/src/native_appearance.rs");
const editorProtocolPath = path.join(root, "apps/world-editor/src/protocol.ts");
const migrationPath = path.join(root, "database/migrations/0026_character_appearance.sql");

const characterAppearanceBlock = Buffer.from("", "base64").toString("utf8");
const playerAppearanceHelpers = Buffer.from("", "base64").toString("utf8");
const authoritativeSync = Buffer.from("", "base64").toString("utf8");
const remoteSource = Buffer.from("", "base64").toString("utf8");
const appearanceUiSource = Buffer.from("", "base64").toString("utf8");

function fail(message) {
  console.error("\nV36.95 PATCH FAILED: " + message);
  process.exit(1);
}
function count(source, needle) {
  return source.split(needle).length - 1;
}
function replaceOnce(source, needle, replacement, label) {
  const hits = count(source, needle);
  if (hits !== 1) fail(`${label}: expected 1 occurrence, found ${hits}`);
  return source.replace(needle, replacement);
}
function normalize(source) {
  return source.replace(/[ \t]*(?:\r?\n)+$/u, "\n");
}

for (const file of [
  typesPath,
  protocolPath,
  persistencePath,
  worldPath,
  serverMainPath,
  statePath,
  playerPath,
  clientMainPath,
  remotePath,
  appearanceUiPath,
  editorProtocolPath,
  migrationPath,
]) {
  if (!fs.existsSync(file)) {
    fail(`missing ${path.relative(root, file)}; extract the COMPLETE V36.95 ZIP into repo root first`);
  }
}

let types = fs.readFileSync(typesPath, "utf8");
let protocol = fs.readFileSync(protocolPath, "utf8");
let persistence = fs.readFileSync(persistencePath, "utf8");
let world = fs.readFileSync(worldPath, "utf8");
let serverMain = fs.readFileSync(serverMainPath, "utf8");
let state = fs.readFileSync(statePath, "utf8");
let player = fs.readFileSync(playerPath, "utf8");
let clientMain = fs.readFileSync(clientMainPath, "utf8");
let editorProtocol = fs.readFileSync(editorProtocolPath, "utf8");
const currentRemote = fs.readFileSync(remotePath, "utf8");
const currentAppearanceUi = fs.readFileSync(appearanceUiPath, "utf8");
const migration = fs.readFileSync(migrationPath, "utf8");

if (
  types.includes(MARKER) &&
  protocol.includes(MARKER) &&
  persistence.includes(MARKER) &&
  world.includes(MARKER) &&
  serverMain.includes(MARKER) &&
  state.includes(MARKER) &&
  player.includes(MARKER) &&
  clientMain.includes(MARKER) &&
  currentRemote.includes(MARKER) &&
  currentAppearanceUi.includes(MARKER) &&
  editorProtocol.includes(MARKER)
) {
  console.log("V36.95 already applied.");
  process.exit(0);
}

if (!player.includes(REQUIRED) || !clientMain.includes(REQUIRED) || !currentAppearanceUi.includes(REQUIRED)) {
  fail("V36.94.1 Character Customization Recovery must be applied before V36.95.");
}
if (!currentRemote.includes("TIBIAGAME_V36_92_REMOTE_EQUIPMENT_REPLICATION")) {
  fail("V36.92 remote equipment renderer baseline missing.");
}
if (!protocol.includes("pub const PROTOCOL_VERSION: u16 = 31;")) {
  fail("expected protocol version 31 before V36.95.");
}
if (!editorProtocol.includes("export const PROTOCOL_VERSION = 31;")) {
  fail("world-editor protocol version 31 baseline missing.");
}
if (!migration.includes(MARKER)) {
  fail("0026_character_appearance.sql is not the V36.95 migration.");
}

if (!types.includes("pub struct PlayerView {") || !types.includes("    pub outfit: String,\n    pub secondary_skills: Vec<String>,")) {
  fail("game-types PlayerView baseline mismatch.");
}
if (count(persistence, "name, vocation, outfit, secondary_skills") !== 3) {
  fail("persistence character SELECT/RETURNING baseline mismatch.");
}
for (const anchor of [
  "struct CharacterRow {",
  "pub struct CharacterRecord {",
  "pub async fn save_outfit(",
  "fn character_from_row(row: CharacterRow) -> CharacterRecord {",
]) {
  if (!persistence.includes(anchor)) fail(`persistence baseline missing '${anchor}'`);
}

for (const anchor of [
  "use game_types::{PlayerView, Position};",
  "        outfit,\n        secondary_skills,",
  "            character.outfit,\n            character.secondary_skills,",
  '            "knight".to_owned(),\n            Vec::new(),',
  "            outfit,\n            secondary_skills,\n            position,",
  "            Ok(ClientMessage::SetSecondarySkills { skills }) => {",
]) {
  if (!serverMain.includes(anchor)) fail(`server main baseline missing '${anchor}'`);
}

if (!world.includes("pub fn set_player_outfit(&mut self, id: EntityId, outfit: String)")) {
  fail("world set_player_outfit baseline missing.");
}
if (!state.includes("ServerMessage::PlayerOutfitChanged { player_id, outfit } => {")) {
  fail("native client PlayerOutfitChanged baseline missing.");
}

const oldLocalSync =
`pub(crate) fn sync_local_character_appearance_resource(
    mut commands: Commands,
    identity: Res<LocalIdentity>,
    appearance: Option<ResMut<LocalCharacterAppearance>>,
) {
    let Some(mut appearance) = appearance else {
        commands.insert_resource(LocalCharacterAppearance::legacy_preset(&identity.outfit));
        return;
    };

    if !appearance.customized && appearance.last_legacy_outfit != identity.outfit {
        *appearance = LocalCharacterAppearance::legacy_preset(&identity.outfit);
    }
}

`;
if (!player.includes(MARKER) && !player.includes(oldLocalSync)) {
  fail("V36.94.1 local appearance resource baseline mismatch.");
}
if (!player.includes("fn appearance_layer_depth_bias(category: &str) -> f32 {")
    && !player.includes("pub(crate) fn appearance_layer_depth_bias(category: &str) -> f32 {")) {
  fail("appearance layer depth helper missing.");
}

const singleRemoteEquipment =
`            .add_systems(
                Update,
                remote_player_sprites::sync_remote_player_equipment_layers
                    .after(remote_player_sprites::sync_remote_player_sprites)
                    .run_if(single_window_game_active),
            )
`;
const directRemoteEquipment =
`        .add_systems(
            Update,
            remote_player_sprites::sync_remote_player_equipment_layers
                .after(remote_player_sprites::sync_remote_player_sprites),
        )
`;
if (!clientMain.includes(MARKER)) {
  if (count(clientMain, singleRemoteEquipment) !== 1) fail("single-window remote equipment schedule mismatch");
  if (count(clientMain, directRemoteEquipment) !== 1) fail("direct remote equipment schedule mismatch");
}

for (const anchor of [
  'export type CharacterOutfit = "knight" | "mage" | "ranger" | "rogue";',
  '  | { type: "set_outfit"; outfit: CharacterOutfit }',
  '  | { type: "player_outfit_changed"; player_id: string; outfit: CharacterOutfit }',
]) {
  if (!editorProtocol.includes(anchor)) fail(`world-editor protocol baseline missing '${anchor}'`);
}

if (checkOnly) {
  console.log("V36.95 PRECHECK PASSED");
  console.log("Will bump protocol 31 -> 32 and add CharacterAppearance to PlayerView.");
  console.log("PostgreSQL migration 0026 stores the full appearance definition per character.");
  console.log("F9 Save becomes server-authoritative; the old V36.94 local JSON is migrated once when safe.");
  console.log("Remote players will render body/head/face/hair/beard/base clothing plus V36.90 equipment.");
  console.log("No appearance choice is tied to vocation/outfit.");
  process.exit(0);
}

// -------------------------------------------------------------------------
// Shared CharacterAppearance contract.
// -------------------------------------------------------------------------
if (!types.includes(MARKER)) {
  types = replaceOnce(
    types,
    "use uuid::Uuid;\n",
    "use uuid::Uuid;\n\n// " + MARKER + "\n",
    "game-types marker",
  );
  types = replaceOnce(
    types,
    "#[derive(Debug, Clone, Serialize, Deserialize)]\n#[serde(rename_all = \"camelCase\")]\npub struct PlayerView {",
    characterAppearanceBlock +
      "\n#[derive(Debug, Clone, Serialize, Deserialize)]\n#[serde(rename_all = \"camelCase\")]\npub struct PlayerView {",
    "CharacterAppearance contract",
  );
  types = replaceOnce(
    types,
    "    pub outfit: String,\n    pub secondary_skills: Vec<String>,",
    "    pub outfit: String,\n    #[serde(default)]\n    pub appearance: CharacterAppearance,\n    pub secondary_skills: Vec<String>,",
    "PlayerView appearance field",
  );
}
fs.writeFileSync(typesPath, normalize(types), "utf8");

// -------------------------------------------------------------------------
// Protocol 32.
// -------------------------------------------------------------------------
if (!protocol.includes(MARKER)) {
  protocol = replaceOnce(
    protocol,
    "// TIBIAGAME_V36_92_REMOTE_EQUIPMENT_REPLICATION\n",
    "// TIBIAGAME_V36_92_REMOTE_EQUIPMENT_REPLICATION\n// " + MARKER + "\n",
    "protocol marker",
  );
  protocol = replaceOnce(
    protocol,
    "pub const PROTOCOL_VERSION: u16 = 31;",
    "pub const PROTOCOL_VERSION: u16 = 32;",
    "protocol version",
  );
  protocol = replaceOnce(
    protocol,
    "    CreatureView, GroundItem, ItemDefinition, ItemInstance, NpcView, PlayerView, Position,\n",
    "    CharacterAppearance, CreatureView, GroundItem, ItemDefinition, ItemInstance, NpcView,\n    PlayerView, Position,\n",
    "protocol CharacterAppearance import",
  );
  protocol = replaceOnce(
    protocol,
    `    SetOutfit {
        outfit: String,
    },
`,
    `    SetOutfit {
        outfit: String,
    },
    SetAppearance {
        appearance: CharacterAppearance,
    },
`,
    "SetAppearance client message",
  );
  protocol = replaceOnce(
    protocol,
    `    PlayerOutfitChanged {
        player_id: game_types::EntityId,
        outfit: String,
    },
`,
    `    PlayerOutfitChanged {
        player_id: game_types::EntityId,
        outfit: String,
    },
    PlayerAppearanceChanged {
        player_id: game_types::EntityId,
        appearance: CharacterAppearance,
    },
`,
    "PlayerAppearanceChanged server message",
  );
}
fs.writeFileSync(protocolPath, normalize(protocol), "utf8");

// -------------------------------------------------------------------------
// PostgreSQL persistence.
// -------------------------------------------------------------------------
if (!persistence.includes(MARKER)) {
  persistence = "// " + MARKER + "\n" + persistence;
  persistence = replaceOnce(
    persistence,
    "use game_types::{EntityId, GroundItem, ItemInstance, Position, ProfessionSkillView};",
    "use game_types::{CharacterAppearance, EntityId, GroundItem, ItemInstance, Position, ProfessionSkillView};",
    "persistence CharacterAppearance import",
  );
  persistence = replaceOnce(
    persistence,
    "    outfit: String,\n    secondary_skills: Vec<String>,",
    "    outfit: String,\n    appearance_json: String,\n    secondary_skills: Vec<String>,",
    "CharacterRow appearance field",
  );
  persistence = replaceOnce(
    persistence,
    "    pub outfit: String,\n    pub secondary_skills: Vec<String>,",
    "    pub outfit: String,\n    pub appearance: CharacterAppearance,\n    pub secondary_skills: Vec<String>,",
    "CharacterRecord appearance field",
  );

  persistence = persistence.replaceAll(
    "name, vocation, outfit, secondary_skills",
    "name, vocation, outfit, appearance_json, secondary_skills",
  );

  const saveSecondaryAnchor = `    pub async fn save_secondary_skills(
`;
  persistence = replaceOnce(
    persistence,
    saveSecondaryAnchor,
`    pub async fn save_appearance(
        &self,
        character_id: EntityId,
        appearance: &CharacterAppearance,
    ) -> Result<(), sqlx::Error> {
        let raw = serde_json::to_string(appearance)
            .map_err(|error| sqlx::Error::Protocol(error.to_string()))?;
        sqlx::query(
            "UPDATE characters SET appearance_json = $2, updated_at = NOW() WHERE id = $1",
        )
        .bind(character_id)
        .bind(raw)
        .execute(&self.pool)
        .await?;
        Ok(())
    }

` + saveSecondaryAnchor,
    "save_appearance persistence method",
  );

  persistence = replaceOnce(
    persistence,
    "fn character_from_row(row: CharacterRow) -> CharacterRecord {\n    CharacterRecord {",
`fn character_from_row(row: CharacterRow) -> CharacterRecord {
    let appearance = serde_json::from_str::<CharacterAppearance>(&row.appearance_json)
        .ok()
        .filter(|appearance| appearance.is_valid())
        .unwrap_or_else(|| CharacterAppearance::from_legacy_outfit(&row.outfit));

    CharacterRecord {`,
    "character appearance decode",
  );
  persistence = replaceOnce(
    persistence,
    "        outfit: row.outfit,\n        secondary_skills: row.secondary_skills,",
    "        outfit: row.outfit,\n        appearance,\n        secondary_skills: row.secondary_skills,",
    "CharacterRecord appearance projection",
  );
}
fs.writeFileSync(persistencePath, normalize(persistence), "utf8");

// -------------------------------------------------------------------------
// Authoritative world state.
// -------------------------------------------------------------------------
if (!world.includes(MARKER)) {
  world = replaceOnce(
    world,
    "// TIBIAGAME_V36_92_REMOTE_EQUIPMENT_REPLICATION\n",
    "// TIBIAGAME_V36_92_REMOTE_EQUIPMENT_REPLICATION\n// " + MARKER + "\n",
    "world marker",
  );
  world = replaceOnce(
    world,
    "    CreatureAttack, CreatureView, EntityId, GroundItem, ItemDefinition, ItemInstance,\n",
    "    CharacterAppearance, CreatureAttack, CreatureView, EntityId, GroundItem, ItemDefinition,\n    ItemInstance,\n",
    "world CharacterAppearance import",
  );
  world = replaceOnce(
    world,
    "    pub fn set_player_outfit(&mut self, id: EntityId, outfit: String) -> Result<(), &'static str> {",
`    pub fn set_player_appearance(
        &mut self,
        id: EntityId,
        appearance: CharacterAppearance,
    ) -> Result<(), &'static str> {
        let player = self.players.get_mut(&id).ok_or("unknown_player")?;
        player.view.appearance = appearance;
        Ok(())
    }

    pub fn set_player_outfit(&mut self, id: EntityId, outfit: String) -> Result<(), &'static str> {`,
    "world appearance setter",
  );
}
fs.writeFileSync(worldPath, normalize(world), "utf8");

// -------------------------------------------------------------------------
// Server login + save/broadcast.
// -------------------------------------------------------------------------
if (!serverMain.includes(MARKER)) {
  serverMain = replaceOnce(
    serverMain,
    "// TIBIAGAME_V36_92_REMOTE_EQUIPMENT_REPLICATION\n",
    "// TIBIAGAME_V36_92_REMOTE_EQUIPMENT_REPLICATION\n// " + MARKER + "\n",
    "server marker",
  );
  serverMain = replaceOnce(
    serverMain,
    "use game_types::{PlayerView, Position};",
    "use game_types::{CharacterAppearance, PlayerView, Position};",
    "server CharacterAppearance import",
  );
  serverMain = replaceOnce(
    serverMain,
    "        outfit,\n        secondary_skills,",
    "        outfit,\n        appearance,\n        secondary_skills,",
    "session appearance tuple field",
  );
  serverMain = replaceOnce(
    serverMain,
    "            character.outfit,\n            character.secondary_skills,",
    "            character.outfit,\n            character.appearance,\n            character.secondary_skills,",
    "database character appearance tuple",
  );
  serverMain = replaceOnce(
    serverMain,
    '            "knight".to_owned(),\n            Vec::new(),',
    '            "knight".to_owned(),\n            CharacterAppearance::from_legacy_outfit("knight"),\n            Vec::new(),',
    "ephemeral appearance tuple",
  );
  serverMain = replaceOnce(
    serverMain,
    "            outfit,\n            secondary_skills,\n            position,",
    "            outfit,\n            appearance,\n            secondary_skills,\n            position,",
    "PlayerView appearance field",
  );

  serverMain = replaceOnce(
    serverMain,
    "            Ok(ClientMessage::SetSecondarySkills { skills }) => {",
`            Ok(ClientMessage::SetAppearance { appearance }) => {
                if !appearance.is_valid() {
                    state.private(
                        id,
                        ServerMessage::Error {
                            code: "invalid_appearance".into(),
                            message: "That character appearance is not available".into(),
                        },
                    );
                    continue;
                }

                if let Some(database) = &state.database
                    && let Err(error) = database.save_appearance(id, &appearance).await
                {
                    warn!(%id, %error, "could not save character appearance");
                    state.private(
                        id,
                        ServerMessage::Error {
                            code: "appearance_save_failed".into(),
                            message: "Your appearance could not be saved".into(),
                        },
                    );
                    continue;
                }

                if state
                    .world
                    .write()
                    .await
                    .set_player_appearance(id, appearance.clone())
                    .is_ok()
                {
                    state.broadcast(ServerMessage::PlayerAppearanceChanged {
                        player_id: id,
                        appearance,
                    });
                }
            }
            Ok(ClientMessage::SetSecondarySkills { skills }) => {`,
    "SetAppearance server handler",
  );
}
fs.writeFileSync(serverMainPath, normalize(serverMain), "utf8");

// -------------------------------------------------------------------------
// Native replicated PlayerView state.
// -------------------------------------------------------------------------
if (!state.includes(MARKER)) {
  state = replaceOnce(
    state,
    "// TIBIAGAME_V36_92_REMOTE_EQUIPMENT_REPLICATION\n",
    "// TIBIAGAME_V36_92_REMOTE_EQUIPMENT_REPLICATION\n// " + MARKER + "\n",
    "client state marker",
  );
  state = replaceOnce(
    state,
    `            ServerMessage::PlayerOutfitChanged { player_id, outfit } => {
                if let Some(player) = self.players.get_mut(player_id) {
                    player.outfit = outfit.clone();
                }
            }
`,
    `            ServerMessage::PlayerOutfitChanged { player_id, outfit } => {
                if let Some(player) = self.players.get_mut(player_id) {
                    player.outfit = outfit.clone();
                }
            }
            ServerMessage::PlayerAppearanceChanged {
                player_id,
                appearance,
            } => {
                if let Some(player) = self.players.get_mut(player_id) {
                    player.appearance = appearance.clone();
                }
            }
`,
    "client PlayerAppearanceChanged state",
  );
}
fs.writeFileSync(statePath, normalize(state), "utf8");

// -------------------------------------------------------------------------
// Local appearance now starts from authoritative PlayerView.appearance.
// -------------------------------------------------------------------------
if (!player.includes(MARKER)) {
  player = replaceOnce(
    player,
    "// TIBIAGAME_V36_94_1_CHARACTER_CUSTOMIZATION_RECOVERY\n",
    "// TIBIAGAME_V36_94_1_CHARACTER_CUSTOMIZATION_RECOVERY\n// " + MARKER + "\n",
    "player marker",
  );
  player = replaceOnce(
    player,
    "use game_types::{EntityId, ItemInstance, Position};",
    "use game_types::{CharacterAppearance, EntityId, ItemInstance, Position};",
    "player CharacterAppearance import",
  );
  player = replaceOnce(
    player,
    "#[derive(Component)]\npub(crate) struct PlayerAppearanceLayer {",
    playerAppearanceHelpers +
      "#[derive(Component)]\npub(crate) struct PlayerAppearanceLayer {",
    "local/authoritative conversion helpers",
  );
  player = replaceOnce(
    player,
    oldLocalSync,
    authoritativeSync,
    "authoritative local appearance resource",
  );
  if (player.includes("fn appearance_layer_depth_bias(category: &str) -> f32 {")) {
    player = replaceOnce(
      player,
      "fn appearance_layer_depth_bias(category: &str) -> f32 {",
      "pub(crate) fn appearance_layer_depth_bias(category: &str) -> f32 {",
      "appearance depth helper visibility",
    );
  }
}
fs.writeFileSync(playerPath, normalize(player), "utf8");

// Atomic replacement of the V36.91/V36.92 remote renderer and V36.94.1 UI.
fs.writeFileSync(remotePath, normalize(remoteSource), "utf8");
fs.writeFileSync(appearanceUiPath, normalize(appearanceUiSource), "utf8");

// -------------------------------------------------------------------------
// Remote appearance layers.
// -------------------------------------------------------------------------
if (!clientMain.includes(MARKER)) {
  clientMain = replaceOnce(
    clientMain,
    "// TIBIAGAME_V36_94_1_CHARACTER_CUSTOMIZATION_RECOVERY\n",
    "// TIBIAGAME_V36_94_1_CHARACTER_CUSTOMIZATION_RECOVERY\n// " + MARKER + "\n",
    "client main marker",
  );
  clientMain = replaceOnce(
    clientMain,
    singleRemoteEquipment,
`            .add_systems(
                Update,
                remote_player_sprites::sync_remote_player_appearance_layers
                    .after(remote_player_sprites::sync_remote_player_sprites)
                    .run_if(single_window_game_active),
            )
` + singleRemoteEquipment,
    "single-window remote appearance schedule",
  );
  clientMain = replaceOnce(
    clientMain,
    directRemoteEquipment,
`        .add_systems(
            Update,
            remote_player_sprites::sync_remote_player_appearance_layers
                .after(remote_player_sprites::sync_remote_player_sprites),
        )
` + directRemoteEquipment,
    "direct remote appearance schedule",
  );
}
fs.writeFileSync(clientMainPath, normalize(clientMain), "utf8");

// -------------------------------------------------------------------------
// World editor wire contract.
// -------------------------------------------------------------------------
if (!editorProtocol.includes(MARKER)) {
  editorProtocol = replaceOnce(
    editorProtocol,
    "// TIBIAGAME_V36_92_REMOTE_EQUIPMENT_REPLICATION\n",
    "// TIBIAGAME_V36_92_REMOTE_EQUIPMENT_REPLICATION\n// " + MARKER + "\n",
    "editor protocol marker",
  );
  editorProtocol = replaceOnce(
    editorProtocol,
    "export const PROTOCOL_VERSION = 31;",
    "export const PROTOCOL_VERSION = 32;",
    "editor protocol version",
  );
  editorProtocol = replaceOnce(
    editorProtocol,
    'export type CharacterOutfit = "knight" | "mage" | "ranger" | "rogue";',
`export type CharacterAppearance = {
  body: string;
  head: string;
  face: string;
  hair: string;
  facialHair?: string | null;
  torso: string;
  legs: string;
  feet: string;
  skinTone: string;
  hairColor: string;
  torsoColor: string;
  legsColor: string;
  feetColor: string;
};
export type CharacterOutfit = "knight" | "mage" | "ranger" | "rogue";`,
    "editor CharacterAppearance type",
  );
  editorProtocol = replaceOnce(
    editorProtocol,
    "  outfit: CharacterOutfit;\n  secondarySkills: SecondarySkill[];",
    "  outfit: CharacterOutfit;\n  appearance: CharacterAppearance;\n  secondarySkills: SecondarySkill[];",
    "editor PlayerView appearance",
  );
  editorProtocol = replaceOnce(
    editorProtocol,
    '  | { type: "set_outfit"; outfit: CharacterOutfit }\n',
    '  | { type: "set_outfit"; outfit: CharacterOutfit }\n  | { type: "set_appearance"; appearance: CharacterAppearance }\n',
    "editor SetAppearance client message",
  );
  editorProtocol = replaceOnce(
    editorProtocol,
    '  | { type: "player_outfit_changed"; player_id: string; outfit: CharacterOutfit }\n',
    '  | { type: "player_outfit_changed"; player_id: string; outfit: CharacterOutfit }\n  | { type: "player_appearance_changed"; player_id: string; appearance: CharacterAppearance }\n',
    "editor PlayerAppearanceChanged server message",
  );
}
fs.writeFileSync(editorProtocolPath, normalize(editorProtocol), "utf8");

console.log("V36.95 PATCH APPLIED");
console.log("Protocol 32 + authoritative character appearance persistence/replication are active.");
console.log("V36.94 local JSON is now only a one-time migration source.");

if (process.env.TIBIAGAME_PATCH_SKIP_SERVER_CHECK !== "1") {
  console.log("\nValidating server/types/protocol...");
  try {
    execFileSync("cargo", ["check", "-p", "game-server", "--bin", "game-server"], {
      cwd: root,
      stdio: "inherit",
    });
  } catch {
    fail("game-server cargo check failed");
  }
}
